//! The Open-source licenses dialog (d0071; *15 · Settings → Row · Open-source licenses dialog*, *… · groups & filter*):
//! what `THIRD-PARTY-LICENSES.md` lists, as the dialog draws it. The file is built into the app (the desktop crate
//! reads it with `include_str!`), so nothing comes from the network. It is generated by `scripts/licenses.sh` in a
//! fixed shape, and [`parse`] reads that shape:
//!
//! - `## Rust crates`: one `### <license>` part per distinct license text, each with a `Used by:` list of
//!   `- [<name> <version>](<url>)` lines and the text in a ```` ```text ```` fence;
//! - `## npm packages`: one `### <name> <version>` part per package, a `<license>, from <url>` line and the text.
//!
//! The dialog groups both by license, the largest group first, and folds every group. The things bundled besides
//! the crates and packages (fonts, icons, theme palettes, syntax definitions, and on Windows Microsoft's ConPTY) are
//! [`BUNDLED`], as the frame names them.

use std::collections::BTreeSet;

use serde::Serialize;
use ts_rs::TS;

use otaq_core::naming::PRODUCT_NAME;

use crate::view_models::theme_credits;

/// A thing bundled with the app that isn't a crate or a package, as the frame lists it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Bundled {
    pub project: &'static str,
    /// Its repository; none for the theme palettes, whose sources are in Theme credits.
    pub source: Option<&'static str>,
    pub license: &'static str,
}

pub const BUNDLED: [Bundled; 5] = [
    Bundled {
        project: "Geist and Geist Mono fonts",
        source: Some("https://github.com/vercel/geist-font"),
        license: "SIL Open Font License 1.1",
    },
    Bundled {
        project: "Lucide icons",
        source: Some("https://github.com/lucide-icons/lucide"),
        license: "ISC",
    },
    Bundled {
        project: "Theme palettes",
        source: None,
        license: "MIT",
    },
    Bundled {
        project: "Syntax definitions (Files tab)",
        source: Some("https://github.com/sublimehq/Packages"),
        license: "Sublime HQ Packages license",
    },
    // d0117 point 4: Windows sessions run in it.
    Bundled {
        project: "Microsoft's ConPTY (Windows)",
        source: Some("https://github.com/microsoft/terminal"),
        license: "MIT",
    },
];

/// One row of the bundled list.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, TS)]
#[ts(rename = "LicensesBundledRow")]
pub struct BundledRow {
    pub project: String,
    /// What the row's second line says: the repository without `https://`, or "9 projects".
    pub source_text: String,
    /// The source link's address; none on the theme palettes, which link to Theme credits instead.
    pub source: Option<String>,
    pub license: String,
}

/// A crate or a package under a license.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, TS)]
#[ts(rename = "LicensesItem")]
pub struct Item {
    pub name: String,
    pub version: String,
    /// The repository, as the file links it.
    pub source: String,
    /// The repository without `https://` and `.git`.
    pub source_text: String,
}

/// The crates (or packages) under one license, with that license's texts.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, TS)]
#[ts(rename = "LicensesGroup")]
pub struct Group {
    pub license: String,
    pub items: Vec<Item>,
    /// Every distinct text of this license (each with its own copyright lines), in the file's order.
    pub texts: Vec<String>,
    /// A line under the list: MPL-2.0 asks that the source stays available.
    pub note: Option<String>,
}

/// *Open-source licenses · dialog*.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, TS)]
#[ts(rename = "LicensesDialog")]
pub struct View {
    pub title: String,
    pub description: String,
    pub filter_placeholder: String,
    pub bundled_heading: String,
    pub bundled: Vec<BundledRow>,
    /// "Rust crates · 364".
    pub rust_heading: String,
    pub rust: Vec<Group>,
    /// "npm packages · 9".
    pub npm_heading: String,
    pub npm: Vec<Group>,
    pub source_label: String,
    pub credits_label: String,
    pub show_text_label: String,
    pub hide_text_label: String,
    /// The filter's result line: `{count}` and `{query}` are filled in by the page.
    pub result_one: String,
    pub result_many: String,
    /// A group's count while filtering: "4 of 542".
    pub count_of: String,
    pub no_match: String,
    pub clear_label: String,
    /// The shortcut that focuses the filter: "⌘F" on macOS, "Ctrl+F" elsewhere.
    pub filter_keys: String,
    pub filter_hint: String,
    pub close_hint: String,
    pub copy_label: String,
    pub copied_label: String,
    pub done_label: String,
    /// What Copy all notices puts on the clipboard: the whole file.
    pub notices: String,
}

/// The parsed file: the Rust crates and the npm packages, grouped by license.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Parsed {
    pub rust: Vec<Group>,
    pub npm: Vec<Group>,
}

impl Parsed {
    /// How many different crates (name and version) the Rust part lists; a crate under two licenses counts once.
    pub fn rust_count(&self) -> usize {
        unique(&self.rust)
    }

    pub fn npm_count(&self) -> usize {
        unique(&self.npm)
    }

    /// Whether `url` is one the dialog links to: only those open from it.
    pub fn links_to(&self, url: &str) -> bool {
        BUNDLED.iter().any(|b| b.source == Some(url))
            || self
                .rust
                .iter()
                .chain(&self.npm)
                .flat_map(|g| &g.items)
                .any(|i| i.source == url)
    }
}

fn unique(groups: &[Group]) -> usize {
    groups
        .iter()
        .flat_map(|g| &g.items)
        .map(|i| (i.name.as_str(), i.version.as_str()))
        .collect::<BTreeSet<_>>()
        .len()
}

/// A license as the dialog names it: "BSD 3-Clause" for cargo-about's `BSD 3-Clause "New" or "Revised" License`.
pub fn license_name(name: &str) -> String {
    let name = name.trim();
    match name {
        "zlib License" => return "zlib".into(),
        "ISC License" => return "ISC".into(),
        "Creative Commons Zero v1.0 Universal" => return "CC0 1.0".into(),
        _ => {}
    }
    // `BSD 2-Clause "Simplified" License`, `BSD 3-Clause "New" or "Revised" License`.
    match name.find(" \"") {
        Some(i) if name.ends_with("\" License") => name[..i].to_owned(),
        _ => name.to_owned(),
    }
}

/// The repository as the rows show it.
pub fn source_text(url: &str) -> String {
    let url = url.trim_end_matches('/');
    let url = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))
        .unwrap_or(url);
    url.strip_suffix(".git").unwrap_or(url).to_owned()
}

/// Reads `THIRD-PARTY-LICENSES.md` (see the module comment for its shape).
pub fn parse(md: &str) -> Parsed {
    #[derive(PartialEq)]
    enum Part {
        None,
        Rust,
        Npm,
    }
    let mut part = Part::None;
    let mut rust: Vec<(String, Vec<Item>, String)> = Vec::new();
    let mut npm: Vec<(String, Vec<Item>, String)> = Vec::new();
    let mut fence: Option<String> = None;
    for line in md.lines() {
        if let Some(text) = fence.as_mut() {
            if line == "```" {
                let text = fence.take().unwrap_or_default();
                let last = match part {
                    Part::Rust => rust.last_mut(),
                    Part::Npm => npm.last_mut(),
                    Part::None => None,
                };
                if let Some(last) = last {
                    last.2 = text.trim_matches('\n').to_owned();
                }
            } else {
                text.push_str(line);
                text.push('\n');
            }
            continue;
        }
        if line.starts_with("```") {
            fence = Some(String::new());
            continue;
        }
        if let Some(heading) = line.strip_prefix("## ") {
            part = match heading.trim() {
                "Rust crates" => Part::Rust,
                "npm packages" => Part::Npm,
                _ => Part::None,
            };
            continue;
        }
        match part {
            Part::Rust => {
                if let Some(license) = line.strip_prefix("### ") {
                    rust.push((license_name(license), Vec::new(), String::new()));
                } else if let (Some(item), Some(last)) = (crate_line(line), rust.last_mut()) {
                    last.1.push(item);
                }
            }
            Part::Npm => {
                if let Some(heading) = line.strip_prefix("### ") {
                    let (name, version) = heading.rsplit_once(' ').unwrap_or((heading, ""));
                    npm.push((
                        String::new(),
                        vec![Item {
                            name: name.to_owned(),
                            version: version.to_owned(),
                            source: String::new(),
                            source_text: String::new(),
                        }],
                        String::new(),
                    ));
                } else if let (Some((license, url)), Some(last)) =
                    (line.rsplit_once(", from "), npm.last_mut())
                    && last.0.is_empty()
                {
                    last.0 = license.trim().to_owned();
                    if let Some(item) = last.1.first_mut() {
                        item.source = url.trim().to_owned();
                        item.source_text = source_text(url);
                    }
                }
            }
            Part::None => {}
        }
    }
    Parsed {
        rust: group(rust),
        npm: group(npm),
    }
}

/// `- [tokio 1.47.1](https://github.com/tokio-rs/tokio)`.
fn crate_line(line: &str) -> Option<Item> {
    let rest = line.strip_prefix("- [")?;
    let (label, rest) = rest.split_once("](")?;
    let url = rest.strip_suffix(')')?;
    let (name, version) = label.rsplit_once(' ')?;
    Some(Item {
        name: name.to_owned(),
        version: version.to_owned(),
        source: url.to_owned(),
        source_text: source_text(url),
    })
}

/// The parts by license: items sorted by name, texts kept once each in the file's order, the largest group first.
fn group(parts: Vec<(String, Vec<Item>, String)>) -> Vec<Group> {
    let mut groups: Vec<Group> = Vec::new();
    for (license, items, text) in parts {
        let at = match groups.iter().position(|g| g.license == license) {
            Some(i) => i,
            None => {
                let note = license
                    .starts_with("Mozilla Public License")
                    .then(|| "Source code: linked next to each crate.".to_owned());
                groups.push(Group {
                    license: license.clone(),
                    items: Vec::new(),
                    texts: Vec::new(),
                    note,
                });
                groups.len() - 1
            }
        };
        let g = &mut groups[at];
        for item in items {
            if !g.items.contains(&item) {
                g.items.push(item);
            }
        }
        if !text.is_empty() && !g.texts.contains(&text) {
            g.texts.push(text);
        }
    }
    for g in &mut groups {
        g.items
            .sort_by(|a, b| a.name.cmp(&b.name).then(a.version.cmp(&b.version)));
    }
    groups.sort_by(|a, b| {
        b.items
            .len()
            .cmp(&a.items.len())
            .then(a.license.cmp(&b.license))
    });
    groups
}

/// The dialog for the notices file `md`; `mac` picks the filter shortcut's spelling.
pub fn view(md: &str, mac: bool) -> View {
    let parsed = parse(md);
    let bundled = BUNDLED
        .iter()
        .map(|b| BundledRow {
            project: b.project.to_owned(),
            source_text: match b.source {
                Some(url) => source_text(url),
                None => format!("{} projects", theme_credits::CREDITS.len()),
            },
            source: b.source.map(str::to_owned),
            license: b.license.to_owned(),
        })
        .collect();
    View {
        title: "Open-source licenses".into(),
        description: format!(
            "These projects’ licenses ask for their notices to ship with {PRODUCT_NAME}. Copyright stays with their authors."
        ),
        filter_placeholder: "Filter by name or license".into(),
        bundled_heading: "Bundled with the app".into(),
        bundled,
        rust_heading: format!("Rust crates · {}", parsed.rust_count()),
        npm_heading: format!("npm packages · {}", parsed.npm_count()),
        rust: parsed.rust,
        npm: parsed.npm,
        source_label: "Open the source".into(),
        credits_label: "See Theme credits".into(),
        show_text_label: "Show license text".into(),
        hide_text_label: "Hide license text".into(),
        result_one: "1 crate matches “{query}”".into(),
        result_many: "{count} crates match “{query}”".into(),
        count_of: "{count} of {total}".into(),
        no_match: "No crate or license matches “{query}”".into(),
        clear_label: "Clear filter".into(),
        filter_keys: if mac { "⌘F" } else { "Ctrl+F" }.into(),
        filter_hint: "filter".into(),
        close_hint: "close".into(),
        copy_label: "Copy all notices".into(),
        copied_label: "Copied".into(),
        done_label: "Done".into(),
        notices: md.to_owned(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = r#"# Third-party licenses

## Bundled with the app

| What | Source | License |
|---|---|---|
| Geist | https://github.com/vercel/geist-font | OFL |

## Rust crates

- MIT License

### MIT License

Used by:

- [tokio 1.47.1](https://github.com/tokio-rs/tokio)
- [anyhow 1.0.0](https://github.com/dtolnay/anyhow)

```text
MIT License

# Not a heading: a line of the text.
Copyright (c) Tokio
```

### Apache License 2.0

Used by:

- [tao 0.37.1](https://github.com/tauri-apps/tao)

```text
Apache License
```

### MIT License

Used by:

- [option-ext 0.2.0](https://github.com/soc/option-ext.git)
- [tokio 1.47.1](https://github.com/tokio-rs/tokio)

```text
MIT License

Copyright (c) Someone else
```

### BSD 3-Clause "New" or "Revised" License

Used by:

- [brotli 9.0.0](https://github.com/dropbox/rust-brotli)

```text
BSD
```

### Mozilla Public License 2.0

Used by:

- [option-ext 0.2.0](https://github.com/soc/option-ext.git)

```text
MPL
```

## npm packages

The page's production packages.

- react 19.3.0 (MIT)

### react 19.3.0

MIT, from https://github.com/facebook/react

```text
MIT License react
```

### @tauri-apps/api 2.12.3

Apache-2.0 OR MIT, from https://github.com/tauri-apps/tauri

```text
Apache tauri
```
"#;

    #[test]
    fn groups_by_license_largest_first_with_each_text_once() {
        let p = parse(SAMPLE);
        let licenses: Vec<&str> = p.rust.iter().map(|g| g.license.as_str()).collect();
        assert_eq!(
            licenses,
            [
                "MIT License",
                "Apache License 2.0",
                "BSD 3-Clause",
                "Mozilla Public License 2.0"
            ]
        );
        let mit = &p.rust[0];
        let names: Vec<&str> = mit.items.iter().map(|i| i.name.as_str()).collect();
        assert_eq!(
            names,
            ["anyhow", "option-ext", "tokio"],
            "sorted, tokio once"
        );
        assert_eq!(mit.texts.len(), 2, "two different copyright holders");
        assert!(
            mit.texts[0].contains("# Not a heading"),
            "a # line inside a fence is text"
        );
        assert_eq!(mit.note, None);
        assert!(p.rust[3].note.is_some(), "MPL says where the source is");
    }

    #[test]
    fn a_crate_under_two_licenses_counts_once() {
        let p = parse(SAMPLE);
        assert_eq!(p.rust_count(), 5);
        assert_eq!(p.npm_count(), 2);
    }

    #[test]
    fn npm_packages_by_license() {
        let p = parse(SAMPLE);
        let npm: Vec<(&str, &str)> = p
            .npm
            .iter()
            .map(|g| (g.license.as_str(), g.items[0].name.as_str()))
            .collect();
        assert_eq!(
            npm,
            [("Apache-2.0 OR MIT", "@tauri-apps/api"), ("MIT", "react")]
        );
        assert_eq!(p.npm[1].items[0].version, "19.3.0");
        assert_eq!(p.npm[1].items[0].source_text, "github.com/facebook/react");
        assert_eq!(p.npm[1].texts, ["MIT License react"]);
    }

    #[test]
    fn names_and_sources_as_the_frame_shows_them() {
        assert_eq!(
            license_name("BSD 3-Clause \"New\" or \"Revised\" License"),
            "BSD 3-Clause"
        );
        assert_eq!(
            license_name("BSD 2-Clause \"Simplified\" License"),
            "BSD 2-Clause"
        );
        assert_eq!(license_name("zlib License"), "zlib");
        assert_eq!(license_name("Unicode License v3"), "Unicode License v3");
        assert_eq!(
            source_text("https://github.com/soc/option-ext.git"),
            "github.com/soc/option-ext"
        );
    }

    #[test]
    fn only_listed_sources_open() {
        let p = parse(SAMPLE);
        assert!(p.links_to("https://github.com/tokio-rs/tokio"));
        assert!(p.links_to("https://github.com/facebook/react"));
        assert!(p.links_to("https://github.com/vercel/geist-font"));
        assert!(!p.links_to("https://example.com"));
    }

    #[test]
    fn the_dialog_counts_and_bundles() {
        let v = view(SAMPLE, true);
        assert_eq!(v.filter_keys, "⌘F");
        assert_eq!(view(SAMPLE, false).filter_keys, "Ctrl+F");
        assert_eq!(v.rust_heading, "Rust crates · 5");
        assert_eq!(v.npm_heading, "npm packages · 2");
        let palettes = &v.bundled[2];
        assert_eq!(palettes.source, None);
        assert_eq!(palettes.source_text, "9 projects");
        assert_eq!(v.bundled[0].source_text, "github.com/vercel/geist-font");
        assert_eq!(v.bundled[4].source_text, "github.com/microsoft/terminal");
        assert_eq!(v.notices, SAMPLE);
    }
}
